exercise.referenceSolution:
class Base { protected: int clamp(int x) const { return x < 0 ? 0 : x > 100 ? 100 : x; } };
class Probe : public Base { public: int read(int x) const { return clamp(x); } };
int solve(int a,int b) { const Probe p; return p.read(a)+p.read(b); }
